/* Review 01: schedule screen only. Browser-local design state; no external scheduling calls. */
(()=>{
'use strict';const F=window.F,M=F?.v38Management;if(!M)return;
const previous={page:F.pages.schedule,render:F.render,close:F.closeModal,navigate:F.navigate},e=F.e;
const S=F.v40Schedule={tab:'upcoming',q:'',draftQuery:'',from:'',to:'',sort:'가까운 일정순',page:0,mode:null,editor:null,period:null,error:null,allowClose:false,pending:null,focus:null};
const deviceZone40=Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Seoul';
const canEdit=()=>M.can('edit','schedule');
const action=(label,a,icon='',cls='',attrs='')=>F.btn(label,'v40-schedule-'+a,icon,cls,attrs);
const stop=ev=>{ev.preventDefault();ev.stopImmediatePropagation();},now=()=>M.clock??Date.now(),zone=()=>F.v38Account?.locale.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Seoul';
function parts(at,z=zone()){const p=Object.fromEntries(new Intl.DateTimeFormat('sv-SE',{timeZone:z,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(at)).map(v=>[v.type,v.value]));return {date:p.year+'-'+p.month+'-'+p.day,time:p.hour+':'+p.minute};}
function epoch(date,time,z=zone()){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!/^\d{2}:\d{2}$/.test(time))return NaN;const [y,m,d]=date.split('-').map(Number),[h,n]=time.split(':').map(Number),target=Date.UTC(y,m-1,d,h,n);let at=target;for(let i=0;i<3;i++){const p=parts(at,z),[a,b,c]=p.date.split('-').map(Number),[hh,mm]=p.time.split(':').map(Number);at=target-(Date.UTC(a,b-1,c,hh,mm)-at);}const p=parts(at,z);return p.date===date&&p.time===time?at:NaN;}
const at=r=>Number.isFinite(r.at)?r.at:epoch(r.date,r.time,r.timezone||deviceZone40);
const dateLabel=t=>new Intl.DateTimeFormat('ko-KR',{timeZone:zone(),month:'long',day:'numeric',weekday:'short',...(parts(t).date.slice(0,4)!==parts(now()).date.slice(0,4)?{year:'numeric'}:{})}).format(new Date(t)),timeLabel=t=>new Intl.DateTimeFormat('ko-KR',{timeZone:zone(),hour:'numeric',minute:'2-digit'}).format(new Date(t));
const fullDate=t=>new Intl.DateTimeFormat('ko-KR',{timeZone:zone(),year:'numeric',month:'long',day:'numeric',weekday:'short'}).format(new Date(t));
const zoneLabel=()=>({'Asia/Seoul':'서울 시간','UTC':'UTC','America/New_York':'뉴욕 시간','Europe/London':'런던 시간'}[zone()]||zone().replaceAll('_',' '));
const all=()=>F.viewState==='예약 없음'?[]:M.schedules.filter(r=>Number.isFinite(at(r)));
const rows=()=>all().filter(r=>(S.tab==='upcoming'?at(r)>=now():at(r)<now())&&(!S.q||r.title.normalize('NFKC').toLowerCase().includes(S.q.normalize('NFKC').toLowerCase()))&&(!S.from||parts(at(r)).date>=S.from)&&(!S.to||parts(at(r)).date<=S.to)).sort((a,b)=>S.sort==='제목순'?a.title.localeCompare(b.title,'ko'):['먼 일정순','최근 일정순'].includes(S.sort)?at(b)-at(a):at(a)-at(b));
const filtered=()=>!!(S.q||S.from||S.to);
function periodText(){if(!S.from&&!S.to)return '전체 기간';if(S.from&&S.from===S.to)return Number(S.from.slice(5,7))+'월 '+Number(S.from.slice(8,10))+'일';const short=d=>d?Number(d.slice(5,7))+'. '+Number(d.slice(8,10)):'';return short(S.from)+' – '+short(S.to);}
function table(items){return '<div class="v40-schedule-table" role="table" aria-label="방송 예약 목록"><div class="v40-schedule-thead" role="row"><span role="columnheader">방송 제목</span><span role="columnheader">방송 일시 <small>'+e(zoneLabel())+'</small></span><span role="columnheader" class="v40-manage-label">관리</span></div>'+items.map(r=>'<div class="v40-schedule-row" role="row"><div role="cell" class="v40-schedule-name"><strong title="'+e(r.title)+'">'+e(r.title)+'</strong></div><div role="cell" class="v40-schedule-time"><time datetime="'+new Date(at(r)).toISOString()+'" title="'+e(fullDate(at(r))+' '+timeLabel(at(r)))+'"><span>'+e(dateLabel(at(r)))+'</span><strong>'+e(timeLabel(at(r)))+'</strong></time></div><div role="cell" class="v40-schedule-row-actions">'+(S.tab==='upcoming'&&canEdit()?action('수정','edit','edit','ghost','data-id="'+e(r.id)+'" aria-label="'+e(r.title)+' 예약 수정"')+action('','more','more','icon ghost','data-id="'+e(r.id)+'" aria-label="'+e(r.title)+' 예약 더보기" aria-haspopup="listbox"'):action('상세','detail','','ghost','data-id="'+e(r.id)+'"'))+'</div></div>').join('')+'</div>';}
function page(state){if(!M.can('view','schedule'))return previous.page(state);const result=rows(),count=result.length,pages=Math.max(1,Math.ceil(count/20));S.page=Math.min(S.page,pages-1);const upcoming=all().filter(r=>at(r)>=now()).length,past=all().length-upcoming;
const tabs='<div class="v40-schedule-tabs" role="tablist" aria-label="방송 예약 구분">'+[['upcoming','예정된 방송',upcoming],['past','지난 예약',past]].map(([id,text,n])=>'<button type="button" role="tab" id="v40-schedule-tab-'+id+'" aria-selected="'+(S.tab===id)+'" aria-controls="v40-schedule-panel" tabindex="'+(S.tab===id?0:-1)+'" data-action="v40-schedule-tab" data-value="'+id+'">'+text+'<span>'+n+'</span></button>').join('')+'</div>';
const tools='<div class="v40-schedule-tools"><form id="v40-schedule-search" role="search"><label class="sr-only" for="v40-schedule-query">방송 제목 검색</label><button type="submit" class="icon" aria-label="예약 검색">'+F.icon('search')+'</button><input id="v40-schedule-query" type="search" name="query" maxlength="100" placeholder="방송 제목 검색" value="'+e(S.draftQuery)+'" autocomplete="off">'+action('','clear-query','close','icon ghost','aria-label="검색어 지우기" '+(!S.draftQuery?'hidden':''))+'</form><div class="v40-schedule-filters">'+action(e(periodText()),'period','calendar','v40-period-button '+(S.from||S.to?'has-value':''),'aria-haspopup="dialog"')+action(e(S.sort)+F.icon('chevron'),'sort','','choice-button','aria-label="예약 정렬" aria-haspopup="listbox"')+(filtered()?action('초기화','reset','','ghost v40-filter-reset'):'')+'</div></div>';
let content=M.fault==='load:schedule'?'<div class="v40-schedule-empty" role="status">'+F.icon('alert')+'<h2>예약을 불러오지 못했어요.</h2>'+action('다시 시도','retry','','')+'</div>':count?table(result.slice(S.page*20,S.page*20+20)):'<div class="v40-schedule-empty">'+F.icon(filtered()?'search':'calendar')+'<h2>'+(filtered()?'조건에 맞는 예약이 없어요.':S.tab==='upcoming'?'예정된 방송이 없어요.':'지난 예약이 없어요.')+'</h2>'+(filtered()?action('필터 초기화','reset','','ghost'):'')+'</div>';
if(pages>1&&M.fault!=='load:schedule')content+='<div class="v40-schedule-pagination"><span>'+((S.page*20)+1)+'–'+Math.min(count,(S.page+1)*20)+' / '+count+'개</span><div>'+action('이전','page','arrow','','data-page="'+(S.page-1)+'" '+(!S.page?'disabled':''))+action('다음','page','right','','data-page="'+(S.page+1)+'" '+(S.page===pages-1?'disabled':''))+'</div></div>';
const html=F.page('방송 예약',tabs+'<section id="v40-schedule-panel" role="tabpanel" aria-labelledby="v40-schedule-tab-'+S.tab+'">'+tools+content+'</section>',canEdit()?action('예약 추가','add','plus','primary'):'');
return html.replace('content-page','content-page v40-schedule');}
F.pages.schedule=page;
function field(label,name,type,value,attrs=''){return '<div class="v40-schedule-field"><label for="v40-schedule-'+name+'">'+label+'</label><input id="v40-schedule-'+name+'" name="'+name+'" type="'+type+'" value="'+e(value)+'" '+attrs+'></div>';}
const snapshot=()=>JSON.stringify({title:S.editor?.title||'',date:S.editor?.date||'',time:S.editor?.time||''});
const dirty=()=>!!S.editor&&snapshot()!==S.editor.initial;
function formData(){if(!S.editor)return;const f=F.dialog.querySelector('#v40-schedule-form');if(f)for(const key of ['title','date','time'])S.editor[key]=f.elements[key].value;}
function draw(title,body,footer,sheet=false){F.genericDialog(title,body,'');F.dialog.classList.add('v40-schedule-dialog');F.dialog.classList.toggle('v40-schedule-confirm',S.mode==='discard'||S.mode==='cancel');if(sheet)F.dialog.dataset.mobilePresentation='sheet';else delete F.dialog.dataset.mobilePresentation;F.dialog.querySelector('.modal-head>button').dataset.action='v40-schedule-close';F.dialog.querySelector('.modal-footer').innerHTML=footer;F.labelControls(F.dialog);F.v39Mobile?.polish();F.v39Copy?.polish();requestAnimationFrame(()=>F.dialog.querySelector('input:not([type=hidden]),.modal-footer button')?.focus({preventScroll:true}));}
function editor(id){S.focus=id?'[data-action="v40-schedule-'+(F.root.querySelector('[data-action="v40-schedule-edit"][data-id="'+id+'"]')?.offsetParent?'edit':'more')+'"][data-id="'+id+'"]':'[data-action="v40-schedule-add"]';const r=M.schedules.find(r=>r.id===id),p=r?parts(at(r)):parts(now()+86400000);S.editor={id:id||null,title:r?.title||'',date:p.date,time:r?p.time:'20:00',timezone:zone()};S.editor.initial=snapshot();S.mode='editor';S.error=null;drawEditor();}
function drawEditor(){const d=S.editor;draw(d.id?'예약 수정':'예약 추가','<form id="v40-schedule-form" novalidate>'+field('방송 제목','title','text',d.title,'maxlength="100" autocomplete="off"')+'<div class="v40-schedule-field-pair">'+field('날짜','date','date',d.date)+field('시작 시간','time','time',d.time,'step="60"')+'</div><p class="v40-schedule-timezone">'+F.icon('globe')+e(zoneLabel())+'</p><p id="v40-schedule-error" class="v40-schedule-error" role="alert" hidden></p></form>',action('취소','close','','')+'<button type="submit" form="v40-schedule-form" class="primary" '+(!d.title.trim()||!dirty()?'disabled':'')+'>'+(d.id?'변경 사항 저장':'예약하기')+'</button>');}
function drawDiscard(){draw('변경 내용을 버릴까요?','<p class="v40-schedule-confirm-text">저장하지 않은 내용이 사라져요.</p>',action('계속 작성','continue')+action('버리기','discard','','danger'),true);}
function clear(){S.mode=null;S.editor=null;S.period=null;S.cancelId=null;S.error=null;delete F.dialog.dataset.mobilePresentation;F.dialog.classList.remove('v40-schedule-dialog','v40-schedule-confirm');}
function close(force=false){if(S.busy)return;if(S.mode==='discard'&&!force){S.mode='editor';S.pending=null;drawEditor();return;}if(S.mode==='editor'){formData();if(!force&&dirty()){S.mode='discard';drawDiscard();return;}}if(S.busy)return;const focus=S.focus;clear();const restoreFocus=()=>(F.root.querySelector(focus||'[data-action="v40-schedule-add"]')||F.root.querySelector('[data-action="v40-schedule-add"]'))?.focus({preventScroll:true});if(F.v39Mobile?.afterDialogClose)F.v39Mobile.afterDialogClose(restoreFocus);else requestAnimationFrame(restoreFocus);S.allowClose=true;previous.close();S.allowClose=false;}
function fail(text,name){S.error={text,name};let error=F.dialog.querySelector('#v40-schedule-error');if(!error){error=document.createElement('p');error.id='v40-schedule-error';error.className='v40-schedule-error';error.setAttribute('role','alert');F.dialog.querySelector('.modal-body').append(error);}error.hidden=false;error.textContent=text;const field=F.dialog.querySelector('[name="'+name+'"]');field?.setAttribute('aria-invalid','true');field?.setAttribute('aria-describedby',error.id);field?.focus();}
function save(){if(!canEdit())return fail('예약을 변경할 권한이 없어요.');formData();const d=S.editor;if(!d.title.trim())return fail('방송 제목을 입력하세요.','title');if(d.title.trim().length>100)return fail('방송 제목은 100자 이내로 입력하세요.','title');const value=epoch(d.date,d.time,d.timezone);if(!Number.isFinite(value))return fail('올바른 날짜와 시간을 선택하세요.','date');if(value<=now())return fail('현재 이후의 날짜와 시간을 선택하세요.','date');if([1800000,3600000,7200000].some(offset=>[-offset,offset].some(delta=>{const p=parts(value+delta,d.timezone);return p.date===d.date&&p.time===d.time;})))return fail('두 번 발생하는 시각이에요. 다른 시간을 선택하세요.','time');if(M.schedules.some(r=>r.id!==d.id&&at(r)===value))return fail('같은 시각에 예약된 방송이 있어요.','time');
if(S.busy)return;const editing=!!d.id,r={id:d.id||'schedule-'+Date.now().toString(36),title:d.title.trim(),date:d.date,time:d.time,timezone:d.timezone,at:value,createdAt:new Date(now()).toISOString()};busy(true,editing?'저장 중':'예약 중');setTimeout(()=>{busy(false);if(M.fault==='save'){M.fault=null;fail('예약을 저장하지 못했어요. 다시 시도하세요.');return;}if(editing)Object.assign(M.schedules.find(r=>r.id===d.id),r);else M.schedules.push(r);S.tab='upcoming';S.q=S.draftQuery=S.from=S.to='';S.page=0;S.sort='가까운 일정순';F.viewState='기본';F.writeUrl(true);close(true);F.render();F.toast(editing?'예약을 변경했어요.':'예약을 추가했어요.');},350);}
function busy(on,label='처리 중'){S.busy=on;F.dialog.setAttribute('aria-busy',String(on));F.dialog.querySelectorAll('button').forEach(b=>{if(on)b.dataset.v40WasDisabled=String(b.disabled);b.disabled=on||b.dataset.v40WasDisabled==='true';if(!on)delete b.dataset.v40WasDisabled;});F.dialog.querySelectorAll('input').forEach(n=>n.readOnly=on);const b=F.dialog.querySelector('.modal-footer .primary,.modal-footer .danger');if(b){if(on){b.dataset.v40Label=b.textContent;b.textContent=label;}else if(b.dataset.v40Label){b.textContent=b.dataset.v40Label;delete b.dataset.v40Label;}}}
function period(){S.focus='[data-action="v40-schedule-period"]';S.mode='period';S.period={from:S.from,to:S.to};drawPeriod();}
function drawPeriod(){const d=S.period;draw('기간 선택','<form id="v40-schedule-period-form" novalidate><div class="v40-period-presets">'+action('전체 기간','preset','','','data-days="0"')+action(S.tab==='upcoming'?'앞으로 7일':'최근 7일','preset','','','data-days="7"')+action(S.tab==='upcoming'?'앞으로 30일':'최근 30일','preset','','','data-days="30"')+'</div><div class="v40-schedule-field-pair">'+field('시작일','from','date',d.from)+field('종료일','to','date',d.to)+'</div><p id="v40-schedule-error" class="v40-schedule-error" role="alert" hidden></p></form>',action('초기화','period-reset','','ghost')+'<button type="submit" form="v40-schedule-period-form" class="primary">적용</button>',true);}
function cancel(id){const r=M.schedules.find(r=>r.id===id);if(!r)return;S.mode='cancel';S.cancelId=id;S.focus='[data-action="v40-schedule-more"][data-id="'+id+'"]';draw('예약을 취소할까요?','<div class="v40-schedule-summary"><strong>'+e(r.title)+'</strong><span>'+e(fullDate(at(r)))+' '+e(timeLabel(at(r)))+'</span></div>',action('돌아가기','close')+action('예약 취소','cancel-confirm','','danger'),true);}
function detail(id){S.detailId=id;const r=M.schedules.find(r=>r.id===id);S.mode='detail';S.focus='[data-action="v40-schedule-detail"][data-id="'+id+'"]';draw(at(r)>=now()?'예약 상세':'지난 예약','<div class="v40-schedule-summary"><strong>'+e(r.title)+'</strong><span>'+e(fullDate(at(r)))+'</span><span>'+e(timeLabel(at(r)))+' · '+e(zoneLabel())+'</span></div>',action('닫기','close'));}
F.closeModal=(...args)=>{if(S.mode&&!S.allowClose)return close();return previous.close(...args);};
F.navigate=(id,...args)=>{if(S.busy)return;if(S.mode==='editor'&&dirty()){S.pending=[id,...args];close();return;}if(S.mode)close(true);return previous.navigate(id,...args);};
window.addEventListener('click',ev=>{const b=ev.target.closest?.('button[data-action^="v40-schedule-"]');if(!b||b.disabled)return;stop(ev);const a=b.dataset.action.slice(13);
if(['add','edit','cancel-confirm'].includes(a)&&!canEdit()){if(S.mode)fail('예약을 변경할 권한이 없어요.');return;}if(a==='add')editor();else if(a==='edit')editor(b.dataset.id);else if(a==='detail')detail(b.dataset.id);else if(a==='more'){const id=b.dataset.id;F.openChoice(b,['수정','예약 취소'],null,value=>F.v39Mobile?.afterChoice?F.v39Mobile.afterChoice(()=>value==='수정'?editor(id):cancel(id)):(value==='수정'?editor(id):cancel(id)));}
else if(a==='tab'){S.tab=b.dataset.value;S.q=S.draftQuery.trim();S.page=0;S.sort=S.tab==='upcoming'?'가까운 일정순':'최근 일정순';S.from=S.to='';F.render();F.root.querySelector('[data-action="v40-schedule-tab"][data-value="'+S.tab+'"]')?.focus({preventScroll:true});}
else if(a==='sort')F.openChoice(b,S.tab==='upcoming'?['가까운 일정순','먼 일정순','제목순']:['최근 일정순','오래된 일정순','제목순'],S.sort,value=>{S.sort=value;S.q=S.draftQuery.trim();S.page=0;F.render();F.root.querySelector('[data-action="v40-schedule-sort"]')?.focus({preventScroll:true});});
else if(a==='period')period();else if(a==='reset'){S.q=S.draftQuery=S.from=S.to='';S.page=0;F.render();}else if(a==='retry'){M.fault=null;F.render();}
else if(a==='clear-query'){S.draftQuery='';S.q='';S.page=0;F.render();F.root.querySelector('#v40-schedule-query')?.focus();}
else if(a==='page'){S.page=Math.max(0,+b.dataset.page);F.render();F.root.querySelector('.v40-schedule-tools')?.scrollIntoView({block:'start'});}
else if(a==='close')close();else if(a==='continue'){S.pending=null;S.mode='editor';drawEditor();}else if(a==='discard'){const next=S.pending;S.pending=null;close(true);if(next)previous.navigate(...next);}
else if(a==='cancel-confirm'){if(S.busy)return;busy(true,'취소 중');setTimeout(()=>{busy(false);if(M.fault==='save'){M.fault=null;fail('예약을 취소하지 못했어요. 다시 시도하세요.');return;}M.schedules=M.schedules.filter(r=>r.id!==S.cancelId);close(true);F.render();F.toast('예약을 취소했어요.');},350);}
else if(a==='preset'){const days=+b.dataset.days,today=parts(now()).date,other=parts(now()+(S.tab==='upcoming'?1:-1)*(days-1)*86400000).date;S.period=days?S.tab==='upcoming'?{from:today,to:other}:{from:other,to:today}:{from:'',to:''};drawPeriod();}
else if(a==='period-reset'){S.period={from:'',to:''};drawPeriod();}
},true);
window.addEventListener('input',ev=>{if(ev.target.id==='v40-schedule-query'){S.draftQuery=ev.target.value;const clear=F.root.querySelector('[data-action="v40-schedule-clear-query"]');if(clear)clear.hidden=!S.draftQuery;}if(ev.target.closest?.('#v40-schedule-form')){formData();F.dialog.querySelector('[form="v40-schedule-form"]').disabled=!S.editor.title.trim()||!dirty();F.dialog.querySelectorAll('[aria-invalid]').forEach(n=>{n.removeAttribute('aria-invalid');n.removeAttribute('aria-describedby');});const err=F.dialog.querySelector('#v40-schedule-error');if(err)err.hidden=true;}if(ev.target.closest?.('#v40-schedule-period-form')){F.dialog.querySelectorAll('[aria-invalid]').forEach(n=>{n.removeAttribute('aria-invalid');n.removeAttribute('aria-describedby');});const err=F.dialog.querySelector('#v40-schedule-error');if(err)err.hidden=true;}},true);
window.addEventListener('submit',ev=>{if(ev.target.id==='v40-schedule-search'){stop(ev);S.q=S.draftQuery.trim();S.page=0;F.render();F.root.querySelector('#v40-schedule-query')?.focus({preventScroll:true});}else if(ev.target.id==='v40-schedule-form'){stop(ev);save();}else if(ev.target.id==='v40-schedule-period-form'){stop(ev);const d=Object.fromEntries(new FormData(ev.target));if(d.from&&d.to&&d.from>d.to)return fail('종료일을 시작일 이후로 선택하세요.','to');S.from=d.from;S.to=d.to;S.q=S.draftQuery.trim();S.page=0;close(true);F.render();}},true);
window.addEventListener('keydown',ev=>{const b=ev.target.closest?.('.v40-schedule-tabs [role=tab]');if(!b||!['ArrowLeft','ArrowRight','Home','End'].includes(ev.key))return;stop(ev);const next=ev.key==='Home'?'upcoming':ev.key==='End'?'past':S.tab==='upcoming'?'past':'upcoming';F.root.querySelector('[data-action="v40-schedule-tab"][data-value="'+next+'"]')?.click();},true);
F.render=(...args)=>{const open=!!S.mode&&F.dialog.open,mode=S.mode;if(open&&mode==='editor')formData();if(open&&mode==='period'){const f=F.dialog.querySelector('#v40-schedule-period-form');if(f)S.period=Object.fromEntries(new FormData(f));}const r=previous.render(...args);F.root.querySelectorAll('.sidebar [data-go="schedule"] .nav-label').forEach(n=>n.textContent='방송 예약');if(open&&!F.dialog.open){if(mode==='editor')drawEditor();else if(mode==='discard')drawDiscard();else if(mode==='period')drawPeriod();else if(mode==='cancel')cancel(S.cancelId);else if(mode==='detail')detail(S.detailId);if(S.busy)busy(true,mode==='cancel'?'취소 중':'저장 중');}return r;};
Object.assign(S,{rows,parts,at,epoch,dirty});F.render();
})();